script:
country_event = {
	id = nomads.2005
	title = nomads.2005.name
	desc = nomads.2005.desc
	picture = GFX_evt_sacred_path
	show_sound = event_arkship_bridge

	is_triggered_only = yes

	immediate = {
		random_owned_fleet = {
			limit = {
				any_owned_ship = {
					is_arkship_ship = yes
				}
			}
			solar_system = {
				random_system_planet = {
					save_event_target_as = pilgrim_path_1
				}
			}
		}
		set_country_flag = sacred_sites_survey
		begin_event_chain = {
			event_chain = sacred_sites_visited_chain
			target = root
		}
		owner = {
			set_country_flag = sacred_site_alpha
			random_owned_fleet = {
				limit = {
					any_owned_ship = {
						is_arkship_ship = yes
					}
				}
				solar_system = {
					random_system_planet = {
						enable_special_project = {
							name = "SACRED_SITE_ONE_PROJECT"
							location = this
							owner = root
						}
						# Sacred Site: Emergence
						set_carrier_flag = sacred_emergence_planet@root.owner
					}
				}
			}
		}
	}

	option = {
		name = nomads.2005.a
		add_modifier = {
			modifier = first_light_guidance
		}
	}

	option = {
		name = nomads.2005.b
		add_modifier = {
			modifier = incomplete_texts
		}
	}

	after = {
		hidden_effect = {
			owner = {
				country_event = { id = nomads.2015 days = 3600 }
			}
		}
	}
}

